function validate([text, pattern]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 100000) return 'text needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(text)) return 'text may contain only lowercase letters.';
  if (typeof pattern !== 'string' || !/^[a-z]{2}$/.test(pattern)) return 'pattern must be exactly two lowercase letters.';
  return null;
}

