function maximumSubsequenceCount(text, pattern) {
  const first = pattern[0];
  const second = pattern[1];
  let firstCount = 0;
  let secondCount = 0;
  let pairs = 0;

  for (const c of text) {
    if (c === second) {
      pairs += firstCount;
      secondCount++;
    }
    if (c === first) {
      firstCount++;
    }
  }
  return pairs + Math.max(firstCount, secondCount);
}

