function maximumSubsequenceCount(text, pattern) {
  const count = t => {
    let total = 0;
    for (let i = 0; i < t.length; i++)
      for (let j = i + 1; j < t.length; j++)
        if (t[i] === pattern[0] && t[j] === pattern[1]) total++;
    return total;
  };
  let best = 0;
  for (const extra of pattern)
    for (let pos = 0; pos <= text.length; pos++)
      best = Math.max(best, count(text.slice(0, pos) + extra + text.slice(pos)));
  return best;
}

