function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 4);
  const n = large ? 10000 : 1 + Math.floor(rand() * 10);
  const letter = range => String.fromCharCode(97 + Math.floor(rand() * range));
  let text = '';
  for (let i = 0; i < n; i++) text += letter(letters);
  const pattern = letter(Math.min(26, letters + 1)) + letter(Math.min(26, letters + 1));
  return [text, pattern];
}
